const fs = require('fs');
const http = require('http');

async function exportEnvVars() {
  // Read and parse .env.test
  const content = fs.readFileSync('.env.test', 'utf8');
  const envVars = new Map();

  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, ...valueParts] = line.split('=');
      envVars.set(key.trim(), valueParts.join('=').trim());
    }
  });

  // Create payload
  const payload = {
    source_file: '.env.test',
    environment_variables: Object.fromEntries(envVars),
    total_count: envVars.size
  };

  console.log('JSON Payload (first 500 chars):');
  console.log(JSON.stringify(payload).substring(0, 500) + '...');
  console.log('');

  // Send POST request
  const url = 'http://localhost:47301/api/doc-export';

  try {
    return new Promise((resolve, reject) => {
      const req = http.request({
        hostname: 'localhost',
        port: 47301,
        path: '/api/doc-export',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(JSON.stringify(payload))
        }
      }, (res) => {
        let responseData = '';
        res.on('data', (chunk) => {
          responseData += chunk;
        });
        res.on('end', () => {
          try {
            console.log('✓ Success! Response:');
            const parsedResult = JSON.parse(responseData);
            console.log(JSON.stringify(parsedResult, null, 2));
            resolve();
          } catch (e) {
            console.log('Response received (not JSON):', responseData);
            resolve();
          }
        });
      });

      req.on('error', (err) => {
        console.log('✗ Error:', err.message);
        if (err.code === 'ECONNREFUSED') {
          console.log('  Server not available at localhost:47301');
          console.log('  Please ensure the server is running with:');
          console.log('  --server 47301 or --port 47301');
        }
        reject(err);
      });

      req.write(JSON.stringify(payload));
      req.end();
    });
  } catch (err) {
    console.log('✗ Error:', err.message);
  }
}

exportEnvVars();
