const https = require('https');
const fs = require('fs');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables (skip comments)
const envVars = {};
const lines = envContent.split('\n');
for (const line of lines) {
  const trimmedLine = line.trim();
  if (trimmedLine.startsWith('#') || trimmedLine === '') {
    continue;
  }
  const idx = trimmedLine.indexOf('=');
  if (idx !== -1) {
    const key = trimmedLine.substring(0, idx).trim();
    const value = trimmedLine.substring(idx + 1).trim();
    envVars[key] = value;
  }
}

// Build JSON payload
const payload = {
  environment_variables: envVars
};

console.log('JSON Payload:');
console.log(JSON.stringify(payload, null, 2));

// POST request
const postData = JSON.stringify(payload);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  console.log(`\nResponse Status: ${res.statusCode}`);
  console.log('Response Body:', res.statusCode === 302 || res.statusCode === 301 ? `Following redirect to: ${res.headers.location}` : res.statusCode === 204 ? 'No Content' : '');

  let data = '';
  res.on('data', chunk => {
    data += chunk;
  });

  res.on('end', () => {
    if (data && res.statusCode !== 204) {
      console.log('Response:', data);
    }
  });
});

req.on('error', (error) => {
  console.error('\nError:', error.message);
  console.log('Note: Make sure the server is running at http://localhost:47301/api/doc-export');
});

req.write(postData);
req.end();

